108	/// JavaScript files may hold JSX whatever their extension; TypeScript files only in `.tsx`, since `<T>x` is a cast
109	/// elsewhere.
110	fn source_type_for(path: &Utf8Path) -> SourceType {
111	    let source_type = SourceType::from_path(path.as_std_path()).unwrap_or_else(|_| SourceType::ts());
112	    if source_type.is_javascript() { source_type.with_jsx(true) } else { source_type }
113	}
114	
115	fn parse_and_extract(path: &Utf8Path, source: &str, profile: AnalysisProfile) -> Extraction {
116	    let allocator = Allocator::default();
117	    // Parentheses carry no meaning here and a `ParenthesizedExpression` node would only add a level to every walk.
118	    let options = ParseOptions { preserve_parens: false, ..ParseOptions::default() };
119	    let parsed = Parser::new(&allocator, source, source_type_for(path)).with_options(options).parse();
120	    // The recovered program is still used below, so record the diagnostics rather than discarding the parse.
121	    let had_parse_errors = parsed.fatal_error || !parsed.diagnostics.is_empty();
122	
123	    let mut extractor = Extractor { path, source, profile, lines: LineIndex::new(source), out: Extraction::default() };
124	    for statement in &parsed.program.body {
125	        extractor.statement(statement);
126	    }
127	    if profile == AnalysisProfile::Full {
128	        extractor.jsx(&parsed.program);
129	    }
130	    Extraction { had_parse_errors, ..extractor.out }
131	}
132	
133	/// Maps byte offsets to 1-based line numbers.
134	struct LineIndex {
135	    newlines: Vec<usize>,
136	}
137	
138	impl LineIndex {
139	    fn new(source: &str) -> Self {
140	        Self { newlines: source.bytes().enumerate().filter(|&(_, byte)| byte == b'\n').map(|(i, _)| i).collect() }
141	    }
142	
143	    fn line(&self, offset: u32) -> usize {
144	        self.newlines.partition_point(|&newline| newline < offset as usize) + 1
145	    }
146	}
147	
148	struct Extractor<'s> {
149	    path: &'s Utf8Path,
150	    source: &'s str,
151	    profile: AnalysisProfile,
152	    lines: LineIndex,
153	    out: Extraction,
154	}
155	
156	impl Extractor<'_> {
157	    fn structural(&self) -> bool {
158	        self.profile != AnalysisProfile::Dependencies
159	    }
160	
161	    fn text(&self, span: Span) -> &str {
162	        self.source.get(span.start as usize..span.end as usize).unwrap_or_default()
163	    }
164	
165	    fn statement(&mut self, statement: &Statement<'_>) {
166	        match statement {
167	            Statement::ImportDeclaration(decl) => self.import(decl),
168	            Statement::ExportDeclaration(decl) => self.export_declaration(decl),
169	            Statement::ExportNamedDeclaration(decl) => self.export_named(decl),
170	            Statement::ExportFromDeclaration(decl) => self.export_from(decl),
171	            Statement::ExportDefaultDeclaration(decl) => self.export_default(decl),
172	            Statement::ExportAllDeclaration(decl) => self.export_all(decl),
173	            Statement::FunctionDeclaration(function) => {
174	                self.function(function);
175	            }
176	            Statement::ClassDeclaration(class) => {
177	                self.class(class);
178	            }
179	            Statement::TSInterfaceDeclaration(decl) => {
180	                self.symbol(decl.id.name.as_str(), SymbolKind::Interface, decl.span, None);
181	            }
182	            Statement::TSTypeAliasDeclaration(decl) => {
183	                self.symbol(decl.id.name.as_str(), SymbolKind::TypeAlias, decl.span, None);
184	            }
185	            Statement::TSEnumDeclaration(decl) => {
186	                self.symbol(decl.id.name.as_str(), SymbolKind::Enum, decl.span, None);
187	            }
188	            Statement::VariableDeclaration(decl) => {
189	                self.variables(decl);
190	            }
191	            _ => {}
192	        }
193	        if self.profile == AnalysisProfile::Full {
194	            self.block(statement);
195	        }
196	    }
197	
198	    fn symbol(&mut self, name: &str, kind: SymbolKind, span: Span, signature: Option<String>) {
199	        if !self.structural() {
200	            return;
201	        }
202	        self.out.symbols.push(SymbolEntry {
203	            name: name.to_owned(),
204	            kind,
205	            line: self.lines.line(span.start),
206	            signature,
207	            owner: None,
208	            trait_impl: None,
209	            visibility: None,
210	            kind_detail: None,
211	        });
212	    }
213	
214	    fn export(&mut self, name: String, span: Span, re_export: bool) {
215	        if !self.structural() {
216	            return;
217	        }
218	        self.out.exports.push(ExportRecord { name, line: self.lines.line(span.start), re_export });
219	    }
220	
221	    /// Records a function symbol and returns its name; anonymous functions have none.
222	    fn function(&mut self, function: &Function<'_>) -> Option<String> {
223	        let name = function.id.as_ref()?.name.as_str();
224	        let signature = self.function_signature(function);
225	        self.symbol(name, SymbolKind::Function, function.span, Some(signature));
226	        Some(name.to_owned())
227	    }
228	
229	    /// The function's text up to its body, on one line: `function f(a: A): B`.
230	    fn function_signature(&self, function: &Function<'_>) -> String {
231	        let end = function.body.as_ref().map_or(function.span.end, |body| body.span.start);
232	        let head = self.text(Span::new(function.span.start, end));
233	        head.split_whitespace().collect::<Vec<_>>().join(" ").trim_end_matches(';').trim_end().to_owned()
234	    }
235	
236	    fn class(&mut self, class: &Class<'_>) -> Option<String> {
237	        let name = class.id.as_ref()?.name.as_str();
238	        self.symbol(name, SymbolKind::Class, class.span, None);
239	        Some(name.to_owned())
240	    }
241	
242	    fn variables(&mut self, decl: &VariableDeclaration<'_>) -> Vec<String> {
243	        let mut names = Vec::new();
244	        for declarator in &decl.declarations {
245	            if let BindingPattern::BindingIdentifier(id) = &declarator.id {
246	                self.symbol(id.name.as_str(), SymbolKind::Variable, declarator.span, None);
247	                names.push(id.name.as_str().to_owned());
248	            }
249	        }
250	        names
251	    }
252	
253	    /// Records the symbols a declaration introduces and returns their names.
254	    fn declaration(&mut self, decl: &Declaration<'_>) -> Vec<String> {
255	        match decl {
256	            Declaration::FunctionDeclaration(function) => self.function(function).into_iter().collect(),
257	            Declaration::ClassDeclaration(class) => self.class(class).into_iter().collect(),
258	            Declaration::TSInterfaceDeclaration(decl) => {
259	                self.symbol(decl.id.name.as_str(), SymbolKind::Interface, decl.span, None);
260	                vec![decl.id.name.as_str().to_owned()]
261	            }
262	            Declaration::TSTypeAliasDeclaration(decl) => {
263	                self.symbol(decl.id.name.as_str(), SymbolKind::TypeAlias, decl.span, None);
264	                vec![decl.id.name.as_str().to_owned()]
265	            }
266	            Declaration::TSEnumDeclaration(decl) => {
267	                self.symbol(decl.id.name.as_str(), SymbolKind::Enum, decl.span, None);
268	                vec![decl.id.name.as_str().to_owned()]
269	            }
270	            Declaration::VariableDeclaration(decl) => self.variables(decl),
271	            Declaration::TSExternalModuleDeclaration(_)
272	            | Declaration::TSNamespaceDeclaration(_)
273	            | Declaration::TSGlobalDeclaration(_)
274	            | Declaration::TSImportEqualsDeclaration(_) => Vec::new(),
275	        }
276	    }
277	
278	    fn import(&mut self, decl: &ImportDeclaration<'_>) {
279	        let specifier = decl.source.value.as_str().to_owned();
280	        if decl.import_kind.is_type() {
281	            self.out.type_only_imports.push(specifier);
282	            return;
283	        }
284	        let mut bindings = Vec::new();
285	        for specifier in decl.specifiers.iter().flatten() {
286	            match specifier {
287	                ImportDeclarationSpecifier::ImportSpecifier(named) => {
288	                    if !named.import_kind.is_type() {
289	                        bindings.push(DependencyBinding {
290	                            imported: module_export_name(&named.imported),
291	                            local: named.local.name.as_str().to_owned(),
292	                            kind: BindingKind::Named,
293	                        });
294	                    }
295	                }
296	                ImportDeclarationSpecifier::ImportDefaultSpecifier(default) => bindings.push(DependencyBinding {
297	                    imported: "default".to_owned(),
298	                    local: default.local.name.as_str().to_owned(),
299	                    kind: BindingKind::Default,
300	                }),
301	                ImportDeclarationSpecifier::ImportNamespaceSpecifier(namespace) => bindings.push(DependencyBinding {
302	                    imported: "*".to_owned(),
303	                    local: namespace.local.name.as_str().to_owned(),
304	                    kind: BindingKind::Namespace,
305	                }),
306	            }
307	        }
308	        self.dependency(decl.source.value.as_str(), decl.span, bindings);
309	    }
310	
311	    fn dependency(&mut self, specifier: &str, span: Span, bindings: Vec<DependencyBinding>) {
312	        self.out.dependencies.push(DependencyRecord {
313	            line: self.lines.line(span.start),
314	            bindings,
315	            target: DependencyTarget::File {
316	                specifier: specifier.to_owned(),
317	                resolved: None,
318	                is_relative: specifier.starts_with('.'),
319	            },
320	        });
321	    }
322	
323	    /// `export function f() {}`, `export const x = 1`.
324	    fn export_declaration(&mut self, decl: &ExportDeclaration<'_>) {
325	        for name in self.declaration(&decl.declaration) {
326	            self.export(name, decl.span, false);
327	        }
328	    }
329	
330	    /// `export { a, b as c }`.
331	    fn export_named(&mut self, decl: &ExportNamedDeclaration<'_>) {
332	        for specifier in &decl.specifiers {
333	            self.export(module_export_name(&specifier.exported), decl.span, false);
334	        }
335	    }
336	
337	    /// `export { a } from './m'`. A type-only re-export adds no runtime dependency.
338	    fn export_from(&mut self, decl: &ExportFromDeclaration<'_>) {
339	        for specifier in &decl.specifiers {
340	            self.export(module_export_name(&specifier.exported), decl.span, true);
341	        }
342	        if decl.export_kind.is_type() {
343	            return;
344	        }
345	        let bindings = decl
346	            .specifiers
347	            .iter()
348	            .filter(|specifier| !specifier.export_kind.is_type())
349	            .map(|specifier| DependencyBinding {
350	                imported: module_export_name(&specifier.local),
351	                local: module_export_name(&specifier.exported),
352	                kind: BindingKind::Named,
353	            })
354	            .collect();
355	        self.dependency(decl.source.value.as_str(), decl.span, bindings);
356	    }
357	
358	    fn export_default(&mut self, decl: &ExportDefaultDeclaration<'_>) {
359	        self.export("default".to_owned(), decl.span, false);
360	        match &decl.declaration {
361	            ExportDefaultDeclarationKind::FunctionDeclaration(function) => {
362	                self.function(function);
363	            }
364	            ExportDefaultDeclarationKind::ClassDeclaration(class) => {
365	                self.class(class);
366	            }
367	            _ => {}
368	        }
369	    }
370	
371	    fn export_all(&mut self, decl: &ExportAllDeclaration<'_>) {
372	        let (name, kind) = match &decl.exported {
373	            Some(exported) => (module_export_name(exported), BindingKind::Namespace),
374	            None => ("*".to_owned(), BindingKind::Glob),
375	        };
376	        self.export(name.clone(), decl.span, true);
377	        if !decl.export_kind.is_type() {
378	            let binding = DependencyBinding { imported: "*".to_owned(), local: name, kind };
379	            self.dependency(decl.source.value.as_str(), decl.span, vec![binding]);
380	        }
381	    }
382	
383	    fn block(&mut self, statement: &Statement<'_>) {
384	        let Some(node_kind) = statement_kind(statement) else { return };
385	        if matches!(statement, Statement::ImportDeclaration(_)) {
386	            return;
387	        }
388	        let span = statement.span();
389	        let code = self.text(span);
390	        if code.trim().is_empty() {
391	            return;
392	        }
393	        let symbol_signature = match (node_kind, statement_function(statement)) {
394	            (SymbolKind::Function, Some(function)) => Some(self.function_signature(function)),
395	            _ => None,
396	        };
397	        let block = CodeBlock {
398	            file: self.path.to_owned(),
399	            line_start: self.lines.line(span.start),
400	            line_end: self.lines.line(span.end),
401	            node_kind,
402	            code: code.to_owned(),
403	            symbol_signature,
404	            matched_lines: Vec::new(),
405	            matched_keywords: Vec::new(),
406	        };
407	        self.out.blocks.push(block);
408	    }
409	
410	    fn jsx(&mut self, program: &Program<'_>) {
411	        let mut collector = JsxCollector { lines: &self.lines, found: Vec::new() };
412	        collector.visit_program(program);
413	        self.out.jsx_elements = collector.found;
414	    }
415	}
