543	    #[test]
544	    fn a_panic_becomes_the_degraded_extraction() {
545	        let extraction = guarded(|| panic!("boom"));
546	        assert!(extraction.had_parse_errors);
547	        assert!(extraction.symbols.is_empty());
548	        assert!(extraction.dependencies.is_empty());
549	        assert!(extraction.exports.is_empty());
550	        assert!(extraction.blocks.is_empty());
551	        assert!(extraction.jsx_elements.is_empty());
552	        assert!(extraction.type_only_imports.is_empty());
553	    }
