555	    #[test]
556	    fn a_run_that_does_not_panic_is_returned_untouched() {
557	        let extraction = guarded(|| Extraction { type_only_imports: vec!["x".to_owned()], ..Extraction::default() });
558	        assert!(!extraction.had_parse_errors);
559	        assert_eq!(extraction.type_only_imports, ["x"]);
