1	//! Pure extraction for one TypeScript or JavaScript file.
2	//!
3	//! The parse owns its arena. Everything leaving this module is owned data, so no arena-borrowed node escapes.
4	
5	use std::panic::{AssertUnwindSafe, catch_unwind};
6	
7	use camino::Utf8Path;
8	use oxc_allocator::Allocator;
9	use oxc_ast::ast::{
10	    BindingPattern, Class, Declaration, ExportAllDeclaration, ExportDeclaration, ExportDefaultDeclaration,
11	    ExportDefaultDeclarationKind, ExportFromDeclaration, ExportNamedDeclaration, Function, ImportDeclaration,
12	    ImportDeclarationSpecifier, JSXAttributeItem, JSXAttributeName, JSXAttributeValue, JSXElement, JSXElementName,
13	    JSXMemberExpression, JSXMemberExpressionObject, ModuleExportName, Program, Statement, VariableDeclaration,
14	};
15	use oxc_ast_visit::{Visit, walk};
16	use oxc_parser::{ParseOptions, Parser};
17	use oxc_span::{GetSpan, SourceType, Span};
18	
