417	/// The kind of block a top-level statement makes, or `None` when it is not one.
418	fn statement_kind(statement: &Statement<'_>) -> Option<SymbolKind> {
419	    match statement {
420	        Statement::FunctionDeclaration(_) => Some(SymbolKind::Function),
421	        Statement::ClassDeclaration(_) => Some(SymbolKind::Class),
422	        Statement::TSInterfaceDeclaration(_) => Some(SymbolKind::Interface),
423	        Statement::TSTypeAliasDeclaration(_) => Some(SymbolKind::TypeAlias),
424	        Statement::TSEnumDeclaration(_) => Some(SymbolKind::Enum),
425	        Statement::VariableDeclaration(_) => Some(SymbolKind::Variable),
426	        Statement::ExportDeclaration(export) => {
427	            Some(declaration_kind(&export.declaration).unwrap_or(SymbolKind::Other))
428	        }
429	        Statement::ImportDeclaration(_)
430	        | Statement::ExportNamedDeclaration(_)
431	        | Statement::ExportFromDeclaration(_)
432	        | Statement::ExportDefaultDeclaration(_)
433	        | Statement::ExportAllDeclaration(_) => Some(SymbolKind::Other),
434	        _ => None,
435	    }
436	}
437	
438	fn declaration_kind(decl: &Declaration<'_>) -> Option<SymbolKind> {
439	    match decl {
440	        Declaration::FunctionDeclaration(_) => Some(SymbolKind::Function),
441	        Declaration::ClassDeclaration(_) => Some(SymbolKind::Class),
442	        Declaration::TSInterfaceDeclaration(_) => Some(SymbolKind::Interface),
443	        Declaration::TSTypeAliasDeclaration(_) => Some(SymbolKind::TypeAlias),
444	        Declaration::TSEnumDeclaration(_) => Some(SymbolKind::Enum),
445	        Declaration::VariableDeclaration(_) => Some(SymbolKind::Variable),
446	        Declaration::TSExternalModuleDeclaration(_)
447	        | Declaration::TSNamespaceDeclaration(_)
448	        | Declaration::TSGlobalDeclaration(_)
449	        | Declaration::TSImportEqualsDeclaration(_) => None,
450	    }
451	}
452	
453	/// The function a statement declares, directly or through `export`.
454	fn statement_function<'a, 'b>(statement: &'b Statement<'a>) -> Option<&'b Function<'a>> {
455	    match statement {
456	        Statement::FunctionDeclaration(function) => Some(function),
457	        Statement::ExportDeclaration(export) => match &export.declaration {
458	            Declaration::FunctionDeclaration(function) => Some(function),
459	            _ => None,
460	        },
461	        _ => None,
462	    }
463	}
464	
465	fn module_export_name(name: &ModuleExportName<'_>) -> String {
466	    match name {
467	        ModuleExportName::IdentifierName(id) => id.name.as_str().to_owned(),
468	        ModuleExportName::IdentifierReference(id) => id.name.as_str().to_owned(),
469	        ModuleExportName::StringLiteral(literal) => literal.value.as_str().to_owned(),
470	    }
471	}
