1	//! The TypeScript and JavaScript analyzer.
2	
3	mod parse;
4	
5	use std::sync::Arc;
6	
7	use camino::Utf8Path;
8	
9	use super::file_analysis::FileAnalysis;
10	use super::lang::{AnalysisProfile, AnalyzerCapabilities, CapabilityPrecision, LanguageAnalyzer, LanguageId};
11	use crate::digest::Digest;
12	use crate::error::Result;
13	use crate::types::{LangData, TsData};
14	
15	const LANGUAGES: [LanguageId; 1] = [LanguageId::TypeScript];
16	
17	/// Analyzes TypeScript and JavaScript files with OXC.
18	///
19	/// It is stateless: every call parses its own source and returns owned data. Dependencies keep their specifier as
20	/// written; resolving them to files is not done here.
21	///
22	/// # Examples
23	///
24	/// ```
25	/// use camino::Utf8Path;
26	/// use monokl::analysis::LanguageAnalyzer;
27	/// use monokl::analysis::ts::TsAnalyzer;
28	///
29	/// let analyzer = TsAnalyzer::new();
30	/// assert!(analyzer.supports(Utf8Path::new("src/app.tsx")));
31	/// assert!(!analyzer.supports(Utf8Path::new("types/global.d.ts")));
32	/// ```
33	#[derive(Clone, Copy, Debug, Default)]
34	pub struct TsAnalyzer;
35	
36	impl TsAnalyzer {
37	    /// Creates an analyzer.
38	    ///
39	    /// # Examples
40	    ///
41	    /// ```
42	    /// use monokl::analysis::ts::TsAnalyzer;
43	    ///
44	    /// let _analyzer = TsAnalyzer::new();
45	    /// ```
46	    #[must_use]
47	    pub const fn new() -> Self {
48	        Self
49	    }
50	}
51	
52	impl LanguageAnalyzer for TsAnalyzer {
53	    fn languages(&self) -> &[LanguageId] {
54	        &LANGUAGES
55	    }
56	
57	    fn supports(&self, path: &Utf8Path) -> bool {
58	        !path.as_str().ends_with(".d.ts")
59	            && matches!(path.extension(), Some("ts" | "tsx" | "js" | "jsx" | "mts" | "cts" | "mjs" | "cjs"))
60	    }
61	
62	    fn language_for(&self, path: &Utf8Path) -> Option<LanguageId> {
63	        self.supports(path).then_some(LanguageId::TypeScript)
64	    }
65	
66	    fn capabilities(&self, _language: LanguageId) -> AnalyzerCapabilities {
67	        AnalyzerCapabilities {
68	            blocks: true,
69	            classified_imports: false,
70	            resolved_import_graph: CapabilityPrecision::Unsupported,
71	            refs: CapabilityPrecision::Structural,
72	            definition: CapabilityPrecision::Structural,
73	            inspect_detail: CapabilityPrecision::Structural,
74	        }
75	    }
76	
77	    fn analyze_with_profile(
78	        &self,
79	        path: &Utf8Path,
80	        source: Box<dyn FnOnce() -> Result<String>>,
81	        profile: AnalysisProfile,
82	    ) -> Result<Arc<FileAnalysis>> {
83	        let source = source()?;
84	        let digest = Digest::blake3(source.as_bytes());
85	        let parse::Extraction {
86	            symbols,
87	            dependencies,
88	            exports,
89	            blocks,
90	            jsx_elements,
91	            type_only_imports,
92	            had_parse_errors,
93	        } = parse::extract(path, &source, profile);
94	        Ok(Arc::new(FileAnalysis {
95	            source_path: path.to_owned(),
96	            digest,
97	            profile,
98	            had_parse_errors,
99	            symbols,
100	            dependencies,
101	            exports,
102	            blocks,
103	            lang: LangData::Ts(TsData { jsx_elements, type_only_imports, unresolved_aliases: Vec::new() }),
104	        }))
105	    }
106	}
