133	
134	    type Symbol<'a> = (&'a str, SymbolKind, usize, Option<&'a str>);
135	    type Binding<'a> = (&'a str, &'a str, BindingKind);
136	
137	    fn symbols(analysis: &FileAnalysis) -> Vec<Symbol<'_>> {
138	        analysis.symbols.iter().map(|s| (s.name.as_str(), s.kind, s.line, s.signature.as_deref())).collect()
139	    }
140	
141	    fn exports(analysis: &FileAnalysis) -> Vec<(&str, usize, bool)> {
142	        analysis.exports.iter().map(|e| (e.name.as_str(), e.line, e.re_export)).collect()
143	    }
144	
145	    fn dependencies(analysis: &FileAnalysis) -> Vec<(&str, usize, Vec<Binding<'_>>)> {
146	        analysis
147	            .dependencies
148	            .iter()
149	            .map(|dep| {
150	                let DependencyTarget::File { specifier, resolved, is_relative } = &dep.target else {
151	                    panic!("expected a file target");
152	                };
153	                assert_eq!(*resolved, None);
154	                assert_eq!(*is_relative, specifier.starts_with('.'));
155	                let bindings = dep.bindings.iter().map(|b| (b.imported.as_str(), b.local.as_str(), b.kind)).collect();
156	                (specifier.as_str(), dep.line, bindings)
157	            })
158	            .collect()
159	    }
160	
161	    fn blocks(analysis: &FileAnalysis) -> Vec<(usize, usize, SymbolKind, Option<&str>)> {
162	        analysis
163	            .blocks
164	            .iter()
165	            .map(|b| {
166	                assert_eq!(b.file, analysis.source_path);
167	                (b.line_start, b.line_end, b.node_kind, b.symbol_signature.as_deref())
168	            })
169	            .collect()
170	    }
